import {concurrency,shards,usable,iam,network,cache,recovery} from './logic.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(id,label,value,min=0,max=1000000,step=1)=>`<label class="field">${label}<input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const toggle=(id,label,checked=true)=>`<label class="check"><input id="${id}" type="checkbox" ${checked?'checked':''}>${label}</label>`;
const select=(id,label,options)=>`<label class="field">${label}<select id="${id}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
const wrap=(n,title,desc,controls,body)=>`<div class="eyebrow">ARCHITECTURE LAB ${n} · CHANGE → PREDICT → EXPLAIN</div><h1>${title}</h1><p class="lede">${desc}</p><div class="lab-grid"><div class="panel lab-controls">${controls}</div><div class="panel lab-canvas">${body}</div></div>`;
const diagram=(nodes)=>`<div class="flow" role="img" aria-label="${esc(nodes.map(x=>x[0]).join(' then '))}">${nodes.map(([a,b,c],i)=>`<div class="flow-node ${c||''}"><strong>${a}</strong><small>${b||''}</small></div>${i<nodes.length-1?'<span class="flow-arrow" aria-hidden="true">↓</span>':''}`).join('')}</div>`;
const result=(ok,text)=>`<div class="result ${ok?'pass':'fail'}"><strong>${ok?'PASS · Lolos':'BLOCKED · Terhenti'}</strong><p>${text}</p></div>`;
export const labList=[['iam','01','Permission gates','IAM, boundaries & SCPs'],['network','02','Trace the packet','Routes, security & authorization'],['capacity','03','Capacity workbench','Lambda, Kinesis & subnet math'],['cache','04','Cache economics','Hit ratio, latency & origin load'],['recovery','05','Recovery rehearsal','RPO, RTO & strategy trade-offs'],['triage','06','Service detective','Read the decisive clue']];
export function renderLab(root,id,done){
 const by=id=>root.querySelector('#'+id);const n=id=>{const x=by(id);return Math.max(Number(x.min||0),Math.min(Number(x.max||1e12),Number(x.value)||0));};const yes=id=>by(id).checked;
 if(id==='iam'){
 root.innerHTML=wrap('01','Who actually gets access?','Ubah satu permission gate. Predict the result before reading the evaluation.',toggle('identity','Identity policy allows the action')+toggle('boundary','Attached boundary permits the action')+toggle('scp','Applicable SCP path permits the action')+toggle('deny','An applicable explicit deny exists',false)+'<p class="fine">Scope: a member-account role’s identity-policy path, with a boundary and SCPs. No resource-based grant, session policy, or service-specific condition in this simplified model. Do not generalize this intersection to every IAM request.</p>','<div id="gate-map"></div><div id="gate-result" aria-live="polite"></div>');
 const update=()=>{const v={identity:yes('identity'),boundary:yes('boundary'),scp:yes('scp'),deny:yes('deny')};const r=iam(v);by('gate-map').innerHTML=diagram([['Identity grant',v.identity?'Action allowed':'No Allow',v.identity?'good':'bad'],['Permission ceilings',`Boundary: ${v.boundary?'permits':'blocks'} · SCP: ${v.scp?'permits':'blocks'}`,v.boundary&&v.scp?'good':'bad'],['Explicit deny scan',v.deny?'Deny found':'No applicable deny',v.deny?'bad':'good'],['Decision',r.allow?'ALLOW':'DENY',r.allow?'good':'bad']]);by('gate-result').innerHTML=result(r.allow,r.reason);};root.onchange=update;update();
 }else if(id==='network'){
 root.innerHTML=wrap('02','A route is only one part of access.','Source: private EC2, IPv4 only, no public IPv4. Ikuti packet AND the return path.',select('target','Destination',[['s3','Regional S3 bucket'],['internet','Public internet API']])+select('route','Destination route',[['endpoint','S3 gateway endpoint'],['nat','NAT gateway'],['igw','Internet gateway directly'],['none','No route']])+toggle('sg','Security group allows egress')+toggle('nacl','NACL allows both directions')+toggle('policy','S3 authorization permits request')+'<p class="fine">Assumptions: DNS resolves; NAT has EIP + IGW path and is healthy; S3 endpoint is in the correct Region and route table. Other application and endpoint prerequisites are satisfied.</p>','<div id="net-map"></div><div id="net-result" aria-live="polite"></div>');
 const update=()=>{const v={target:by('target').value,route:by('route').value,sg:yes('sg'),nacl:yes('nacl'),policy:yes('policy')};const r=network(v);by('net-map').innerHTML=diagram([['Private EC2','No public IPv4'],['SG + NACL',v.sg&&v.nacl?'Traffic rules pass':'Traffic rule blocks',v.sg&&v.nacl?'good':'bad'],[({endpoint:'S3 gateway endpoint',nat:'NAT → IGW',igw:'IGW directly',none:'Missing route'})[v.route],'Destination route'],[v.target==='s3'?'S3 bucket':'Internet API',r.ok?'Request succeeds':'Request fails',r.ok?'good':'bad']]);by('net-result').innerHTML=result(r.ok,r.reason);};root.onchange=update;update();
 }else if(id==='capacity'){
 root.innerHTML=`<div class="eyebrow">ARCHITECTURE LAB 03 · CALCULATE THE BOTTLENECK</div><h1>Capacity workbench</h1><p class="lede">Angka adalah starting estimate. Explain your assumptions before adding headroom.</p><div class="calc-grid"><section class="panel"><h2>Lambda concurrency</h2>${number('rps','Requests / second',400)}${number('duration','Average duration (ms)',250,1)}<div id="lambda-result" class="metric-output" aria-live="polite"></div><p>Concurrency ≈ arrival rate × duration in seconds. Jika durasi naik 2×, concurrency doubles at the same rate. Bursts, tail latency and reserved/provisioned settings need separate planning.</p></section><section class="panel"><h2>Kinesis shards</h2>${number('inmb','Incoming MB / second',3.5,0,100000,.1)}${number('records','Incoming records / second',6000)}${number('outmb','Total shared reads MB / second',10,0,100000,.1)}<div id="shard-result" class="metric-output" aria-live="polite"></div><p>Provisioned, evenly distributed small records: per shard 1 MB/s or 1,000 records/s writes; 2 MB/s shared reads. Take the largest ceiling. Hot partition keys can still throttle; enhanced fan-out has different read allocation.</p></section><section class="panel"><h2>IPv4 subnet capacity</h2>${number('prefix','CIDR prefix /',24,16,28)}<div id="ip-result" class="metric-output" aria-live="polite"></div><p>Ordinary AWS IPv4 subnet: 2^(32 − prefix) − 5 reserved addresses. Kurangi kebutuhan load balancers, endpoints and other ENIs before planning instance count.</p></section></div>`;
 const update=()=>{by('lambda-result').innerHTML=`<b>${concurrency(n('rps'),n('duration'))}</b><span>estimated concurrent executions</span><code>${n('rps')} × ${n('duration')/1000} seconds</code>`;by('shard-result').innerHTML=`<b>${Math.max(1,shards(n('inmb'),n('records'),n('outmb')))}</b><span>minimum estimated shard count</span><code>ceil(max(${n('inmb')}, ${n('records')}/1000, ${n('outmb')}/2))</code>`;by('ip-result').innerHTML=`<b>${usable(Math.round(n('prefix'))).toLocaleString()}</b><span>usable IPv4 addresses</span><code>2^(32 − ${Math.round(n('prefix'))}) − 5</code>`;};root.oninput=update;update();
 }else if(id==='cache'){
 root.innerHTML=wrap('04','Make the origin breathe.','Cache hit ratio = bagian request yang dijawab cache. Higher hit rates reduce backend work, but correctness still needs a staleness policy.',number('requests','Client requests / second',1000)+number('hit','Cache hit ratio (%)',80,0,100)+number('origin','Miss latency (ms, whole request)',200,0)+number('fast','Hit latency (ms, whole request)',10,0)+'<p class="fine">Simplified weighted mean. Assumes a stable hit ratio and fixed hit/miss latencies; excludes concurrency and changing queue delays. Use measured end-to-end times.</p>','<div id="cache-chart" aria-live="polite"></div><div class="callout"><strong>Design question · Pikirkan</strong><p>A longer TTL may raise the hit ratio. What happens when a price changes? Choose invalidation, versioned keys, or an acceptable staleness window.</p></div>');
 const update=()=>{const r=cache(n('requests'),n('hit'),n('origin'),n('fast'));by('cache-chart').innerHTML=`<div class="metric-pair"><div class="metric-output"><b>${r.origin.toLocaleString(undefined,{maximumFractionDigits:1})}</b><span>origin requests / second</span></div><div class="metric-output"><b>${r.latency.toFixed(1)}<em> ms</em></b><span>estimated mean latency</span></div></div><div class="stacked" role="img" aria-label="${n('hit')} percent cache hits, ${100-n('hit')} percent origin misses"><span style="width:${n('hit')}%"></span><span style="width:${100-n('hit')}%"></span></div><div class="legend"><span>● Cache hits ${n('hit')}%</span><span>● Origin misses ${100-n('hit')}%</span></div>${diagram([['Clients',`${n('requests')} requests/s`],['Cache',`${(n('requests')-r.origin).toFixed(0)} served here`,'good'],['Origin',`${r.origin.toFixed(0)} requests/s on misses`]])}`;};root.oninput=update;update();
 }else if(id==='recovery'){
 const presets={backup:[240,10,60,120,30,'Backups stored; application must be rebuilt.'],pilot:[5,5,25,10,15,'Data/core services running; application capacity must be created.'],warm:[1,3,8,2,7,'Full application running at reduced capacity; scale and redirect.'],active:[.1,1,0,0,2,'Both locations serve; coordinate state, detect failure, reroute.']};
 root.innerHTML=wrap('05','Can your recovery meet the promise?','RPO = how much data-time you can lose. RTO = how long service can be down. Semua timing di lab ini adalah illustrative assumptions, not AWS SLAs.',select('strategy','Recovery strategy',[['backup','Backup and restore'],['pilot','Pilot light'],['warm','Warm standby'],['active','Multi-site active/active']])+number('rpo','Assumed recoverable data lag (minutes)',240,0,10000,.1)+number('detect','Detect failure (minutes)',10,0,10000,.1)+number('provision','Provision / scale (minutes)',60,0,10000,.1)+number('restore','Restore / promote data (minutes)',120,0,10000,.1)+number('validate','Validate + redirect (minutes)',30,0,10000,.1)+number('target-rpo','Required maximum RPO (minutes)',15,0,10000,.1)+number('target-rto','Required maximum RTO (minutes)',60,0,10000,.1),'<p id="strategy-desc" class="bridge"></p><div id="dr-result" aria-live="polite"></div><p class="fine">For periodic snapshots, use worst-case age of the last usable snapshot, plus any additional backup lag. Replication is not a backup: logical corruption can replicate. Validate actual recovery in drills.</p>');
 const update=()=>{const values=['detect','provision','restore','validate'].map(n);const total=recovery(...values);const rpo=n('rpo');by('strategy-desc').textContent=presets[by('strategy').value][5];by('dr-result').innerHTML=`<div class="metric-pair"><div class="metric-output"><b>${rpo}<em> min</em></b><span>assumed data loss window (RPO)</span></div><div class="metric-output"><b>${+total.toFixed(2)}<em> min</em></b><span>modeled service recovery (RTO)</span></div></div><div class="timeline">${values.map((v,i)=>`<div><span>${['Detect','Provision / scale','Restore / promote','Validate / redirect'][i]}</span><div class="bar-track"><i style="width:${total?v/total*100:0}%"></i></div><b>${v} min</b></div>`).join('')}</div>${result(rpo<=n('target-rpo')&&total<=n('target-rto'),`RPO ${rpo<=n('target-rpo')?'meets':'misses'} target ${n('target-rpo')} min. RTO ${total<=n('target-rto')?'meets':'misses'} target ${n('target-rto')} min. A strategy name alone guarantees neither — buktikan dengan recovery drill.`)}`;};const preset=()=>{const v=presets[by('strategy').value];['rpo','detect','provision','restore','validate'].forEach((id,i)=>by(id).value=v[i]);update();};root.oninput=update;by('strategy').onchange=preset;update();
 }else{
 const cases=[['A lender needs fields and tables extracted from scanned loan forms.','Bank perlu struktur dokumen, bukan hanya label gambar.',['Textract','Rekognition','Polly'],0,'Textract extracts text, forms and tables. Rekognition handles image/video analysis; Polly turns text into speech.'],['Three independent teams need their own durable copy of every order event.','Setiap tim memproses dengan kecepatannya sendiri.',['One shared SQS queue','SNS → three SQS queues','A single ElastiCache key'],1,'SNS fans out, and separate SQS queues provide independent buffering. One queue makes consumers compete for messages.'],['An existing application requires SMB shares integrated with Active Directory.','Protocol dan directory integration adalah decisive constraints.',['S3','EFS','FSx for Windows File Server'],2,'FSx for Windows provides SMB and AD integration. EFS is NFS; S3 is object storage.'],['Analysts want SQL over partitioned Parquet files in S3 without running clusters.','Query data in place; hindari cluster management.',['Athena','RDS for PostgreSQL','Amazon MQ'],0,'Athena queries S3 data using SQL. Optimize partitions and columnar files to reduce scanned data.'],['Security needs to identify sensitive personal data inside S3 objects.','Cari isi data sensitif.',['Inspector','Macie','CloudTrail'],1,'Macie discovers sensitive S3 data. Inspector assesses vulnerabilities; CloudTrail records API activity.'],['A media pipeline must replay yesterday’s events with independent consumers.','Butuh retained stream dan replay.',['SNS alone','NAT gateway','Kinesis Data Streams'],2,'Kinesis retains records for replay and supports independent consumers. SNS push alone is not a replayable event log.'],['A company wants globally static IPs for a latency-sensitive TCP application.','Global network routing, bukan caching objects.',['Global Accelerator','CloudFront','S3 Transfer Acceleration'],0,'Global Accelerator provides static anycast addresses and routes over the AWS network. CloudFront serves HTTP(S) content.'],['A team must reconstruct the sequence of AWS API calls that changed IAM roles.','Siapa melakukan apa dan kapan?',['Config only','CloudTrail','WAF'],1,'CloudTrail records API events. Config tracks resource configuration; WAF filters web requests.'],['A company needs to migrate database rows continuously while the source remains active.','Full load lalu replicate changes sampai cutover.',['Application Migration Service','Storage Gateway','DMS with CDC'],2,'DMS supports full load and ongoing change data capture. Schema conversion and compatibility still require planning.'],['A workflow needs branches, retries and a human approval wait.','Orkestrasi stateful, bukan sekadar event routing.',['Step Functions Standard','An ALB listener rule','CloudFront Function'],0,'A Standard state machine can coordinate long workflows and callback tasks. Design timeout, retries and external idempotency.']];
 let pos=0;const show=()=>{const c=cases[pos];root.innerHTML=`<div class="eyebrow">ARCHITECTURE LAB 06 · CASE ${pos+1} OF ${cases.length}</div><h1>Service detective</h1><p class="lede">Find the requirement that eliminates the alternatives. Cari clue yang menentukan.</p><section class="panel triage"><h2>${c[0]}</h2><p class="bridge">${c[1]}</p><div class="option-list">${c[2].map((v,i)=>`<button data-pick="${i}" class="option"><span>${String.fromCharCode(65+i)}</span>${v}</button>`).join('')}</div><div id="triage-result" aria-live="polite"></div><button class="primary hidden" id="case-next">${pos===cases.length-1?'Start again':'Next case →'}</button></section>`;root.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.pick)===c[3];by('triage-result').innerHTML=result(ok,c[4]);root.querySelectorAll('[data-pick]').forEach(x=>{x.disabled=true;if(Number(x.dataset.pick)===c[3])x.classList.add('correct');});by('case-next').classList.remove('hidden');if(ok)done('triage-'+pos);});by('case-next').onclick=()=>{pos=(pos+1)%cases.length;show();};};show();
 }
 root.insertAdjacentHTML('beforeend','<div class="lab-reflect"><strong>Teach it back · Jelaskan ulang</strong><p>Change one input. Predict the result, then explain the mechanism without looking at the answer. Record the decision and its limitation in your lesson notes.</p></div>');
}
